"""Address validation and decoding utilities.

These helpers let callers verify that an address is well-formed before using it,
which is critical for wallets and exchanges that must never send funds to a
malformed or mistyped destination. All checks are performed locally with the
Python standard library and internal libcrypto primitives.

Supported checks:

* Base58Check addresses (Bitcoin-style P2PKH/P2SH and TRON) with checksum
  verification.
* Native SegWit / Taproot addresses (Bech32 and Bech32m) with witness-program
  rules.
* Ethereum / EVM hex addresses, including EIP-55 mixed-case checksum
  verification.
"""
from __future__ import annotations

from typing import Dict, List, NamedTuple, Optional, Tuple

from .addresses import Bech32, _encode_version_prefix
from .constants import ADDRESS_VERSIONS, BASE58_ALPHABET, BECH32_HRP
from .formats import InvalidFormatError, base58_check_decode
from .hash import keccak256

_RIPPLE_ALPHABET = "rpshnaf39wBUDNEGHJKLM4PQRST7VWXYZ2bcdeCg65jkm8oFqi1tuvAxyz"

# Reverse lookup: version-prefix bytes -> list of (network, address_type).
# Prefixes may be one or two bytes (for example Zcash transparent 0x1CB8), so
# they are keyed by their encoded bytes rather than a single integer.
_BASE58_PREFIX_INDEX: Dict[bytes, List[Tuple[str, str]]] = {}
for _network, _versions in ADDRESS_VERSIONS.items():
    for _kind in ("p2pkh", "p2sh"):
        _prefix = _encode_version_prefix(_versions[_kind])
        _BASE58_PREFIX_INDEX.setdefault(_prefix, []).append((_network, _kind))

# Within a shared prefix, report p2pkh before p2sh so a receive-style address is
# labelled with the more common interpretation when version bytes collide.
for _entries in _BASE58_PREFIX_INDEX.values():
    _entries.sort(key=lambda item: 0 if item[1] == "p2pkh" else 1)

# Longest prefixes first so a two-byte match wins over a one-byte collision.
_BASE58_PREFIXES_BY_LENGTH = sorted(_BASE58_PREFIX_INDEX, key=len, reverse=True)

# Reverse lookup: bech32 hrp -> network.
_BECH32_HRP_INDEX: Dict[str, str] = {hrp: network for network, hrp in BECH32_HRP.items()}


class AddressInfo(NamedTuple):
    """Structured result describing a decoded address."""

    valid: bool
    address_format: Optional[str]  # 'base58check' | 'bech32' | 'bech32m' | 'evm-hex'
    address_type: Optional[str]    # 'p2pkh' | 'p2sh' | 'p2wpkh' | 'p2wsh' | 'p2tr' | 'account' | 'tron'
    networks: Tuple[str, ...]      # possible networks (may be ambiguous)
    witness_version: Optional[int]
    payload: Optional[bytes]       # hash160 / witness program / 20-byte account hash


def decode_base58check_address(
    address: str, *, alphabet: str = BASE58_ALPHABET
) -> Tuple[int, bytes]:
    """Decode a Base58Check address into (version_byte, payload).

    The checksum is verified. Raises InvalidFormatError on any failure.
    """
    decoded = base58_check_decode(address, alphabet=alphabet)
    if len(decoded) < 1:
        raise InvalidFormatError("Base58Check address is too short.")
    return decoded[0], decoded[1:]


def decode_segwit_address(address: str) -> Tuple[str, int, bytes]:
    """Decode a SegWit address into (hrp, witness_version, program)."""
    return Bech32.decode_witness(address)


def _eip55_checksum(address_hex: str) -> str:
    checksum_hash = keccak256(address_hex.encode("ascii")).hex()
    return "".join(
        char.upper() if int(checksum_hash[index], 16) >= 8 else char
        for index, char in enumerate(address_hex)
    )


def is_valid_ethereum_address(address: str, *, require_checksum: bool = False) -> bool:
    """Validate an Ethereum/EVM address.

    When the address is mixed-case its EIP-55 checksum is always verified. When
    ``require_checksum`` is True an all-lowercase or all-uppercase address is
    rejected because it carries no checksum protection.
    """
    if not isinstance(address, str) or not address.startswith(("0x", "0X")):
        return False
    body = address[2:]
    if len(body) != 40:
        return False
    try:
        int(body, 16)
    except ValueError:
        return False

    is_lower = body == body.lower()
    is_upper = body == body.upper()
    if is_lower or is_upper:
        return not require_checksum

    return _eip55_checksum(body.lower()) == body


def to_checksum_address(address: str) -> str:
    """Return the EIP-55 checksummed form of an Ethereum/EVM address."""
    if not isinstance(address, str) or not address.startswith(("0x", "0X")):
        raise InvalidFormatError("Ethereum address must start with 0x.")
    body = address[2:]
    if len(body) != 40:
        raise InvalidFormatError("Ethereum address must be 20 bytes (40 hex chars).")
    try:
        int(body, 16)
    except ValueError as exc:
        raise InvalidFormatError(f"Invalid Ethereum address: {exc}") from exc
    return "0x" + _eip55_checksum(body.lower())


_INVALID_INFO = AddressInfo(False, None, None, tuple(), None, None)


def _segwit_info(address: str) -> AddressInfo:
    try:
        hrp, witness_version, program = decode_segwit_address(address)
    except Exception:  # noqa - malformed SegWit address.
        return _INVALID_INFO
    network = _BECH32_HRP_INDEX.get(hrp)
    if network is None:
        return _INVALID_INFO

    spec = "bech32" if witness_version == 0 else "bech32m"
    if witness_version == 0:
        address_type = "p2wpkh" if len(program) == 20 else "p2wsh"
    elif witness_version == 1 and len(program) == 32:
        address_type = "p2tr"
    else:
        address_type = "witness"
    return AddressInfo(True, spec, address_type, (network,), witness_version, program)


def _ripple_info(address: str) -> AddressInfo:
    try:
        version, payload = decode_base58check_address(address, alphabet=_RIPPLE_ALPHABET)
    except InvalidFormatError:
        return _INVALID_INFO
    if version == 0x00 and len(payload) == 20:
        return AddressInfo(True, "base58check", "account", ("ripple",), None, payload)
    return _INVALID_INFO


def _base58_info(address: str) -> AddressInfo:
    try:
        decoded = base58_check_decode(address)
    except InvalidFormatError:
        return _ripple_info(address)

    # TRON uses the single-byte 0x41 prefix followed by a 20-byte hash.
    if len(decoded) == 21 and decoded[0] == 0x41:
        return AddressInfo(True, "base58check", "tron", ("tron",), None, decoded[1:])

    # Match the longest known version prefix that leaves a 20-byte hash160.
    for prefix in _BASE58_PREFIXES_BY_LENGTH:
        if decoded[:len(prefix)] == prefix and len(decoded) - len(prefix) == 20:
            matches = _BASE58_PREFIX_INDEX[prefix]
            networks = tuple(network for network, _ in matches)
            return AddressInfo(True, "base58check", matches[0][1], networks, None, decoded[len(prefix):])
    return _INVALID_INFO


def get_address_info(address: str) -> AddressInfo:
    """Inspect an address and return structured decoding information.

    Never raises for a malformed address; instead returns ``AddressInfo`` with
    ``valid=False``.
    """
    if not isinstance(address, str) or not address:
        return _INVALID_INFO

    # Ethereum / EVM hex addresses.
    if address.startswith(("0x", "0X")):
        if is_valid_ethereum_address(address):
            return AddressInfo(
                True, "evm-hex", "account", ("ethereum",), None, bytes.fromhex(address[2:].lower())
            )
        return _INVALID_INFO

    # SegWit (Bech32 / Bech32m).
    if "1" in address and address.lower().rsplit("1", 1)[0] in _BECH32_HRP_INDEX:
        return _segwit_info(address)

    # Base58Check (Bitcoin-family, TRON, and Ripple).
    return _base58_info(address)


def validate_address(address: str, network: Optional[str] = None) -> bool:
    """Return True when ``address`` is well-formed.

    When ``network`` is provided the address must also belong to that network
    (matching version byte, HRP, or the EVM address family).
    """
    info = get_address_info(address)
    if not info.valid:
        return False
    if network is None:
        return True

    network = network.lower()
    from .addresses import EVM_COMPATIBLE_NETWORKS

    if info.address_format == "evm-hex":
        return network in EVM_COMPATIBLE_NETWORKS or network == "ethereum"
    return network in info.networks


__all__ = [
    "AddressInfo",
    "decode_base58check_address",
    "decode_segwit_address",
    "is_valid_ethereum_address",
    "to_checksum_address",
    "get_address_info",
    "validate_address",
]
